import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    token_pattern = re.compile(r"\d+|[A-Z][A-Z0-9]*|<>|<=|>=|[^\s]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "~": 3,
        ":": 4,
    }

    def parse(formula):
        values = []
        operators = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "~":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append((op, left, right))

        for token in token_pattern.findall(formula):
            if token[0].isdigit():
                values.append(int(token))
                expect_operand = False
            elif token in functions:
                operators.append((token, len(values)))
                expect_operand = True
            elif token[0].isalpha():
                values.append(token)
                expect_operand = False
            elif token == "(":
                operators.append("(")
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                if operators and isinstance(operators[-1], tuple):
                    name, start = operators.pop()
                    arguments = values[start:]
                    del values[start:]
                    values.append((name, arguments))
                expect_operand = False
            else:
                op = "~" if token == "-" and expect_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "~"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return values[0]

    def argument_nodes(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first, last = argument[1], argument[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield name
            else:
                yield argument

    cache = {}
    active = set()

    for root in cells:
        if root in cache:
            continue

        tasks = [("eval", root)]
        value = 0

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "eval":
                node = task[1]

                if isinstance(node, int):
                    value = node
                elif isinstance(node, str):
                    if node in cache:
                        value = cache[node]
                    elif node not in cells:
                        value = 0
                    elif node in active:
                        value = "#CYCLE!"
                    else:
                        content = cells[node].strip()
                        if content.startswith("="):
                            active.add(node)
                            tasks.append(("finish", node))
                            tasks.append(("eval", parse(content[1:])))
                        else:
                            value = int(content)
                            cache[node] = value
                else:
                    op = node[0]
                    if op == "neg":
                        tasks.append(("negate",))
                        tasks.append(("eval", node[1]))
                    elif op == "IF":
                        condition, then_branch, else_branch = node[1]
                        tasks.append(("choose", then_branch, else_branch))
                        tasks.append(("eval", condition))
                    elif op in functions:
                        tasks.append((
                            "aggregate_next",
                            op,
                            argument_nodes(node[1]),
                            None,
                        ))
                    else:
                        tasks.append(("binary_left", op, node[2]))
                        tasks.append(("eval", node[1]))

            elif kind == "finish":
                name = task[1]
                cache[name] = value
                active.remove(name)

            elif kind == "negate":
                if isinstance(value, int):
                    value = -value

            elif kind == "choose":
                if isinstance(value, int):
                    tasks.append(("eval", task[1] if value else task[2]))

            elif kind == "binary_left":
                if isinstance(value, int):
                    tasks.append(("binary_right", task[1], value))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                if isinstance(value, str):
                    continue

                op, left = task[1], task[2]
                right = value

                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        value = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            value = -value
                elif op == "=":
                    value = int(left == right)
                elif op == "<>":
                    value = int(left != right)
                elif op == "<":
                    value = int(left < right)
                elif op == "<=":
                    value = int(left <= right)
                elif op == ">":
                    value = int(left > right)
                elif op == ">=":
                    value = int(left >= right)

            elif kind == "aggregate_next":
                op, iterator, accumulator = task[1:]
                try:
                    node = next(iterator)
                except StopIteration:
                    value = 0 if accumulator is None else accumulator
                else:
                    tasks.append(("aggregate_done", op, iterator, accumulator))
                    tasks.append(("eval", node))

            elif kind == "aggregate_done":
                if isinstance(value, str):
                    continue

                op, iterator, accumulator = task[1:]
                if accumulator is None:
                    accumulator = value
                elif op == "SUM":
                    accumulator += value
                elif op == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append(("aggregate_next", op, iterator, accumulator))

    return {name: cache[name] for name in cells}
